		return eventHandler(eventHook ? eventHook(e) : e);
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {PreactEvent} e The event object from the browser
 * @private
 */
function eventProxyCapture(e) {
	if (this._listeners) {
		const eventHook = attrGuard.svgAlias.eventNames.optionsRef.event;
		return this._listeners[e.type + true](eventHook ? eventHook(e) : e);
	}
}

